let cachedWordSet: Set<string> | null = null;

export const getEnglishWordSet = (): Set<string> => {
  if (!cachedWordSet) {
    const s = new Set<string>();
    for (let i = 0; i < PACKED_WORDS.length; i += 5) {
      s.add(PACKED_WORDS.slice(i, i + 5));
    }
    for (const a of CRYPTLE_ANSWER_WORDS) {
      s.add(a);
    }
    cachedWordSet = s;
  }
  return cachedWordSet;
};

export const isValidEnglishWord = (word: string): boolean => {
  const upper = word.trim().toUpperCase();
  if (!/^[A-Z]{5}$/.test(upper)) return false;
  return getEnglishWordSet().has(upper);
};
